import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ContentService, PortfolioData } from '../../services/content.service';

@Component({
  selector: 'app-projects',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './projects.component.html'
})
export class ProjectsComponent implements OnInit {
  content!: PortfolioData;

  constructor(private contentService: ContentService) {}

  ngOnInit(): void {
    this.contentService.content$.subscribe(data => {
      this.content = data;
    });
  }

  isPortfolioProject(project: any): boolean {
    if (!project) return false;
    const title = (project.title || '').toLowerCase();
    const url = project.liveUrl || project.live || '';
    return (title.includes('portfolio') || project.id === 4) && url !== '#' && url.length > 0;
  }
}
<div class="projects-container" *ngIf="content">
  <div class="page-header">
    <div>
      <h1 class="page-title">Portfolio Projects & Systems</h1>
      <p class="page-subtitle">Production-ready applications, REST APIs, and database architectures built by Me</p>
    </div>
  </div>

  <div class="projects-grid">
    <div *ngFor="let project of content.projects" class="card project-card">
      <div>
        <div class="project-header">
          <span class="tech-tag font-bold">{{ project.badge || 'Full Stack' }}</span>
          <span class="text-muted-sm font-bold">{{ project.category }}</span>
        </div>
        <h2 class="project-title">{{ project.title }}</h2>
        <p class="text-indigo font-bold" style="margin-bottom: 8px;">{{ project.subtitle }}</p>
        <p class="project-desc">{{ project.description }}</p>

        <div *ngIf="project.features?.length" style="margin-bottom: 16px;">
          <h4 style="font-size: 0.85rem; font-weight: 700; color: #ffffff; margin-bottom: 8px;">Key Deliverables & Specs:</h4>
          <ul class="project-features-list">
            <li *ngFor="let feat of project.features">
              <span style="color: #10b981;">✓</span> {{ feat }}
            </li>
          </ul>
        </div>
      </div>

      <div class="project-footer">
        <div class="tech-tag-group">
          <span *ngFor="let t of project.tech" class="tech-tag">{{ t }}</span>
        </div>

        <div class="project-actions">
          <a *ngIf="project.githubUrl || project.github" [href]="project.githubUrl || project.github" target="_blank" rel="noopener noreferrer" class="btn btn-secondary btn-action" title="View Source Code">
            GitHub ↗
          </a>
          <a *ngIf="isPortfolioProject(project)" [href]="project.liveUrl || project.live" target="_blank" rel="noopener noreferrer" class="btn btn-primary btn-action" title="Live Preview">
            Live Demo ↗
          </a>
        </div>
      </div>
    </div>
  </div>
</div>
